function inv(id){return db.investors.find(x=>x.id===id)}
function com(id){return db.companies.find(x=>x.id===id)}
function activeCompanies(){return db.companies.filter(company=>!company.deletedAt)}
function joined(meeting){return {...meeting,investor:inv(meeting.investorId),company:com(meeting.companyId)}}
function initials(text=""){return text.replace(/[^가-힣A-Za-z]/g,"").slice(0,2)||"PO"}
function esc(text=""){return String(text).replace(/[&<>'"]/g,c=>({"&":"&amp;","<":"&lt;",">":"&gt;","'":"&#39;",'"':"&quot;"}[c]))}
function fmtDate(value){if(!value)return "—";return new Intl.DateTimeFormat("ko-KR",{month:"short",day:"numeric"}).format(new Date(value))}
function fmtMoney(value){if(!value)return "—";return value>=100000000?`${value/100000000}억원`:`${Math.round(value/10000).toLocaleString()}만원`}
function statusClass(value){return ({"검토 중":"review","투자 확정":"confirmed","투자 완료":"completed","보류":"hold","미투자":"declined","예정":"scheduled"})[value]||""}
function today(){return "2026-10-14"}
function overdue(m){return m.followupDate&&m.followupDate<today()&&!['완료','없음'].includes(m.followupStatus)}
function match(...values){const term=query.trim().toLowerCase();return !term||values.some(v=>String(v??"").toLowerCase().includes(term))}
function visibleMeetings(){return db.meetings.map(joined).filter(m=>m.company&&m.investor&&match(m.company.name,m.company.sector,m.investor.name,m.investor.firm,m.memo,m.investmentStatus,m.followupStatus))}
function badge(value,extra=""){return `<span class="badge ${extra||statusClass(value)}">${esc(value)}</span>`}
function showToast(message){const el=document.createElement("div");el.className="toast";el.textContent=message;document.body.appendChild(el);setTimeout(()=>el.remove(),2400)}

