function investorNav(){return `<button class="nav-item active" data-view="investorHome"><i>▣</i><span>포켓데이</span></button><button class="nav-item" data-view="investorReview"><i>▦</i><span>심사 관리</span></button><button class="nav-item" data-view="investorFeedback"><i>✎</i><span>심사평</span></button><button class="nav-item" data-view="investorMeetings"><i>◎</i><span>미팅 관리</span></button>`}
function bindSideNav(){document.querySelectorAll("#sideNav [data-view]").forEach(b=>b.onclick=()=>switchView(b.dataset.view));document.querySelectorAll("#sideNav [data-scroll-target]").forEach(b=>b.onclick=()=>document.getElementById(b.dataset.scrollTarget)?.scrollIntoView({behavior:"smooth",block:"start"}))}
function renderAdminSidebarStats(){const note=document.getElementById("sourceNote");if(!note)return;const total=db.meetings.length;const matched=db.meetings.filter(m=>["예정","진행 중","완료"].includes(m.followupStatus)).length;const matchedRate=total?Math.round(matched/total*100):0;const invested=db.meetings.filter(m=>m.investmentStatus==="투자 완료").length;note.className="source-note admin-stats";note.innerHTML=`<div class="admin-stats-head"><span class="dot"></span><div><strong>CRM 통계</strong><p>미팅 이력 DB 실시간 집계</p></div></div><div class="admin-stats-grid"><article><strong>${matchedRate}<em>%</em></strong><span>후속 미팅 매칭</span><small>${matched}/${total}건 연결</small></article><article><strong>${invested}<em>건</em></strong><span>투자 완료</span><small>누적 완료 건수</small></article></div><div class="admin-match-progress" aria-label="후속 미팅 매칭률 ${matchedRate}%"><i style="width:${matchedRate}%"></i></div>`}
function setRoleChrome(role){const nav=document.getElementById("sideNav");const note=document.getElementById("sourceNote");const subtitle=document.getElementById("brandSubtitle");const profile={avatar:document.getElementById("profileAvatar"),name:document.getElementById("profileName"),role:document.getElementById("profileRole")};document.body.dataset.role=role;document.getElementById("searchBox").hidden=role!=="admin";document.getElementById("topActions").hidden=role!=="admin";document.getElementById("updatedChip").hidden=role!=="admin";if(role==="admin"){subtitle.textContent="Investor CRM";nav.innerHTML=adminNav();renderAdminSidebarStats();profile.avatar.textContent="PO";profile.name.textContent="포켓컴퍼니";profile.role.textContent="CRM 관리자"}else if(role==="company"){subtitle.textContent="Company Portal";nav.innerHTML=companyNav();note.className="source-note";note.innerHTML=`<span class="dot"></span><div><strong>기업 전용 공간</strong><p>우리 기업과 연결된 일정만 보여줍니다.</p></div>`;profile.avatar.textContent="플로";profile.name.textContent="플로우랩";profile.role.textContent="기업 계정"}else{subtitle.textContent="Investor Portal";nav.innerHTML=investorNav();note.className="source-note";note.innerHTML=`<span class="dot"></span><div><strong>심사역 전용 공간</strong><p>담당 기업과 투자 검토를 모아봅니다.</p></div>`;profile.avatar.textContent="김민";profile.name.textContent="김민준";profile.role.textContent="수석 심사역"}bindSideNav()}
function routeEntityId(){return currentView==="investorDetail"?selectedInvestorId:currentView==="companyDetail"?selectedCompanyId:currentView==="investorMeetings"?selectedInvestorCompanyId:""}
function syncRoute(){if(restoringRoute||!currentRole)return;const entityId=routeEntityId();const hash=`#/${encodeURIComponent(currentRole)}/${encodeURIComponent(currentView)}${entityId?`/${encodeURIComponent(entityId)}`:""}`;if(location.hash!==hash)history.pushState(null,"",hash)}
function enterRole(role){currentRole=role;document.getElementById("portalRoot").hidden=true;document.getElementById("workspaceShell").hidden=false;setRoleChrome(role);switchView(roleDefaultViews[role]||"adminHome")}
function leaveWorkspace(){document.getElementById("workspaceShell").hidden=true;document.getElementById("portalRoot").hidden=false;document.querySelector(".sidebar").classList.remove("open");document.body.removeAttribute("data-role");currentRole="";if(!restoringRoute)history.pushState(null,"",`${location.pathname}${location.search}`)}
function restoreRoute(){const [role,requestedView,entityId]=location.hash.replace(/^#\/?/,"").split("/").map(value=>decodeURIComponent(value||""));if(!roleDefaultViews[role]){restoringRoute=true;leaveWorkspace();restoringRoute=false;return}const view=roleViews[role].has(requestedView)?requestedView:roleDefaultViews[role];if(view==="investorDetail"&&entityId)selectedInvestorId=entityId;if(view==="companyDetail"&&entityId)selectedCompanyId=entityId;if(view==="investorMeetings"&&entityId)selectedInvestorCompanyId=entityId;restoringRoute=true;currentRole=role;document.getElementById("portalRoot").hidden=true;document.getElementById("workspaceShell").hidden=false;setRoleChrome(role);switchView(view);restoringRoute=false}

function roleStat(icon,label,value,detail,tone){return `<article class="role-stat-card ${tone}"><div class="role-stat-icon">${icon}</div><div><span>${label}</span><strong>${value}<small>${typeof value==="number"?"건":""}</small></strong><p>${detail}</p></div><b>›</b></article>`}
function roleMeetingCard(m,perspective){const primary=perspective==="company"?m.investor.name:m.company.name;const secondary=perspective==="company"?m.investor.firm:`${m.company.sector} · ${m.company.stage}`;return `<article class="role-meeting-card"><div class="role-meeting-head"><time>${m.date.replaceAll("-",". ")}</time>${badge(m.followupStatus==="없음"?m.investmentStatus:m.followupStatus)}</div><div class="meeting-visual"><span>${perspective==="company"?"INVESTOR MEETING":"COMPANY REVIEW"}</span><i>${initials(primary)}</i></div><h3>${esc(primary)}</h3><p>${esc(secondary)}</p><footer><span>${esc(m.type)}</span><b>${esc(m.investmentStatus)} →</b></footer></article>`}
function roleCalendar(items,accent="blue"){const events=[];items.forEach(m=>{events.push({date:m.date,label:m.type,tone:accent});if(m.followupDate)events.push({date:m.followupDate,label:`${m.followupStatus} 미팅`,tone:m.followupStatus==="완료"?"gray":"mint"})});const start=new Date(2026,8,27);const cells=Array.from({length:42},(_,i)=>{const d=new Date(start);d.setDate(start.getDate()+i);const key=`${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,"0")}-${String(d.getDate()).padStart(2,"0")}`;const dayEvents=events.filter(e=>e.date===key);return `<div class="cal-cell ${d.getMonth()!==9?"muted-day":""} ${key===today()?"today-cell":""}"><span>${d.getDate()}</span>${dayEvents.slice(0,2).map(e=>`<em class="cal-event ${e.tone}">${esc(e.label)}</em>`).join("")}</div>`}).join("");return `<div class="calendar-head"><div><button aria-label="이전 달">‹</button><h3>2026년 10월</h3><button aria-label="다음 달">›</button></div><div class="calendar-legend"><span><i class="blue"></i>미팅</span><span><i class="mint"></i>후속 일정</span></div></div><div class="week-row"><span>일</span><span>월</span><span>화</span><span>수</span><span>목</span><span>금</span><span>토</span></div><div class="calendar-grid">${cells}</div>`}
function emptyRoleCard(message){return `<article class="role-meeting-card empty-role-card"><div class="empty-role-icon">＋</div><h3>${message}</h3><p>새로운 활동이 등록되면 이곳에 표시됩니다.</p></article>`}

function renderCompanyHome(){const company=activeCompanies()[0];if(!company)return `<div class="panel empty">등록된 기업이 없습니다.</div>`;const a=companyAgg(company);const meetings=a.ms.sort((x,y)=>y.date.localeCompare(x.date));const pocketday=meetings.filter(m=>m.type==="포켓데이").length;const upcoming=meetings.filter(m=>["예정","진행 중"].includes(m.followupStatus)).length;return `<div class="role-dashboard company-dashboard"><header class="role-greeting"><div><span class="role-overline">COMPANY DASHBOARD</span><h1>${esc(company.ceo)} 대표님, 안녕하세요! <i>👋</i></h1><p>${esc(company.name)}의 투자 미팅과 포켓데이 활동을 한곳에서 확인하세요.</p></div><div class="company-identity"><span>${initials(company.name)}</span><div><strong>${esc(company.name)}</strong><small>${esc(company.sector)} · ${esc(company.stage)}</small></div></div></header><section class="role-stat-grid" id="company-status">${roleStat("▣","포켓데이 참여",pocketday,"참여한 공식 프로그램","blue")}${roleStat("◎","진행한 미팅",meetings.length,"연결된 전체 투자 미팅","mint")}${roleStat("□","예정된 미팅",upcoming,"후속 일정 기준","purple")}</section><section class="role-section" id="company-history"><div class="role-section-head"><div><span>ACTIVITY</span><h2>포켓데이 참여 및 미팅 이력</h2></div><button>전체 보기 →</button></div><div class="role-card-row">${meetings.map(m=>roleMeetingCard(m,"company")).join("")}${meetings.length<3?Array.from({length:3-meetings.length},()=>emptyRoleCard("다음 투자 미팅을 준비해보세요")).join(""):""}</div></section><section class="role-section calendar-panel" id="company-calendar"><div class="role-section-head"><div><span>SCHEDULE</span><h2>월간 일정</h2></div><button class="outline-action">＋ 미팅 일정 추가</button></div>${roleCalendar(meetings,"blue")}</section></div>`}
function renderInvestorHome(){
  const eventHistory=pocketdaySchedule.map(event=>({...event,status:event.status==="완료"?"참여 완료":"참여 예정"}));
  const companyHistory=eventHistory.flatMap(event=>event.companies.map(company=>({company,event:`${pocketdayLabel(event)} 포켓데이`,date:event.date,status:event.status})));
  const investorName=(document.getElementById("profileName")?.textContent||"김민준").replace(/\s*심사역님?$/," ").trim();
  const reviewedCompanies=new Set(companyHistory.map(item=>item.company)).size;
  const realInterestIds=new Set(db.meetings.filter(meeting=>meeting.type==="포켓데이").map(meeting=>meeting.companyId));
  const interestCount=realInterestIds.size?[...investorInterestCompanyIds].filter(id=>realInterestIds.has(id)).length:investorInterestCompanyIds.size;
  const eventRows=eventHistory.map(event=>`<article class="pocket-history-row" data-pocket-row data-search="${esc(`${event.id} ${event.round||""} ${event.companies.join(" ")}`)}"><div class="pocket-event-info"><time>${esc(event.date)}</time><div><h2>${esc(pocketdayLabel(event))} 포켓데이</h2><span class="pocket-status ${event.status==="참여 완료"?"done":""}">${event.status}</span></div><p>운영구분 · ${esc(pocketdayOperationType(event))}</p></div><div class="pocket-company-list"><strong>참여 기업 ${event.companies.length}개사</strong><div>${event.companies.map(name=>`<span>${esc(name)}</span>`).join("")}</div></div><button class="pocket-row-open" data-pocket-open aria-label="${esc(pocketdayLabel(event))} 포켓데이 심사 관리 열기">›</button></article>`).join("");
  const companyRows=companyHistory.slice(0,10).map(item=>`<article class="pocket-history-row company-view-row" data-pocket-row data-search="${esc(`${item.company} ${item.event}`)}"><div class="pocket-event-info"><time>${item.date}</time><div><h2>${esc(item.company)}</h2><span class="pocket-status ${item.status==="참여 완료"?"done":""}">${item.status}</span></div><p>검토 기업 · 포켓데이 참여 이력</p></div><div class="pocket-company-list"><strong>참여 행사</strong><div><span>${item.event}</span></div></div><button class="pocket-row-open" data-pocket-open aria-label="${esc(item.company)} 심사 관리 열기">›</button></article>`).join("");
  return `<div class="role-dashboard investor-dashboard pocket-history-page investor-home-dashboard"><header class="role-greeting"><div><span class="role-overline">INVESTOR DASHBOARD</span><h1>${esc(investorName)} 심사역님, 안녕하세요! <i>👋</i></h1><p>포켓데이 참여 이력과 관심 기업, 투자 검토 현황을 한곳에서 확인하세요.</p></div></header><section class="role-stat-grid">${roleStat("▣","포켓데이 참여",eventHistory.length,"참여한 공식 프로그램","blue")}${roleStat("◎","검토 기업",reviewedCompanies,"포켓데이 참여 기업 기준","mint")}${roleStat("★","관심 기업",interestCount,"심사 관리에서 표시한 기업","purple")}</section><header class="pocket-history-title investor-home-history-title"><span class="role-overline">ACTIVITY</span><h1>포켓데이 참여 이력</h1><p>참여했던 포켓데이와 기업별 심사 이력을 확인하세요.</p></header><div class="pocket-view-tabs"><button class="${pocketViewMode==="event"?"active":""}" data-pocket-tab="event">포켓데이별 보기</button><button class="${pocketViewMode==="company"?"active":""}" data-pocket-tab="company">기업별 보기</button></div><section class="pocket-history-panel"><div class="pocket-history-tools"><label><span>⌕</span><input type="search" data-pocket-search placeholder="회차 또는 기업명으로 검색해보세요." aria-label="포켓데이 이력 검색"></label><select aria-label="연도 선택"><option>전체 연도</option><option>2026년</option><option>2025년</option></select></div><div class="pocket-history-list ${pocketViewMode==="company"?"company-mode":""}">${pocketViewMode==="event"?eventRows:companyRows}</div><div class="pocket-search-empty" hidden>검색 결과가 없습니다.</div></section></div>`
}

function renderInvestorReview(){
  const companies=db.meetings.filter(m=>m.type==="포켓데이").map(joined).sort((a,b)=>b.date.localeCompare(a.date));
  const rows=companies.map((m,index)=>{const done=m.investmentStatus!=="검토 전"&&index%2===1;const interested=investorInterestCompanyIds.has(m.companyId);return `<div class="review-row"><span class="review-no">${String(index+1).padStart(2,"0")}</span><div class="review-company-with-interest"><button class="interest-toggle ${interested?"active":""}" data-interest-company="${m.companyId}" data-interest-name="${esc(m.company.name)}" aria-pressed="${interested}" aria-label="${esc(m.company.name)} 관심 기업 ${interested?"해제":"표시"}" title="관심 기업 ${interested?"해제":"표시"}">${interested?"★":"☆"}</button><button class="review-company-cell" data-company="${m.companyId}"><i class="review-company-logo logo-${index%5}">${initials(m.company.name)}</i><span><strong>${esc(m.company.name)}</strong><small>${esc(m.company.sector)} · ${esc(m.company.description)}</small></span></button></div><button class="ir-button" data-ir="${m.companyId}"><span>▣</span> IR 보기</button><span class="review-stage">${esc(m.company.stage)}</span><span class="review-status ${done?"done":""}">${done?"작성 완료":"미작성"}</span><button class="review-open" data-company="${m.companyId}" aria-label="${esc(m.company.name)} 상세 보기">›</button></div>`}).join("");
  const examples=[{id:"example-pocket-robotics",name:"포켓로보틱스",sector:"AI·로봇",stage:"Seed"},{id:"example-green-bio-lab",name:"그린바이오랩",sector:"바이오·헬스케어",stage:"Pre-A"}];
  const exampleRows=examples.map((company,index)=>{const interested=investorInterestCompanyIds.has(company.id);return `<div class="review-row review-example-row"><span class="review-no">예시 ${index+1}</span><div class="review-company-with-interest"><button class="interest-toggle ${interested?"active":""}" data-interest-company="${company.id}" data-interest-name="${company.name}" aria-pressed="${interested}" aria-label="${company.name} 관심 기업 ${interested?"해제":"표시"}" title="관심 기업 ${interested?"해제":"표시"}">${interested?"★":"☆"}</button><div class="review-company-cell"><i class="review-company-logo logo-${index%5}">${initials(company.name)}</i><span><strong>${company.name} <em class="example-label">예시</em></strong><small>${company.sector} · 관심 기업 표시 체험용</small></span></div></div><button class="ir-button" disabled><span>▣</span> IR 보기</button><span class="review-stage">${company.stage}</span><span class="review-status">미작성</span><span class="review-example-end">—</span></div>`}).join("");
  return `<div class="role-dashboard investor-dashboard investor-review-page"><header class="review-page-title"><div><span>POCKET DAY REVIEW</span><h1>심사 관리</h1><p>참여 기업의 IR 자료를 확인하고 심사평을 작성하세요.</p></div><span class="review-role-chip">심사역</span></header><section class="review-event-card"><div class="review-event-icon"><span>▥</span></div><div class="review-event-copy"><small>제28회</small><h2>제28회 포켓데이</h2><div><span>▣ 2026. 10. 22. (목) 14:00 - 17:00</span><span>⌖ 온라인 미팅 (Zoom)</span><span>◎ 참여 기업 ${companies.length}개사</span></div></div><span class="review-event-badge">참여 예정</span><button class="review-event-action" data-review-jump>참여 기업 확인 →</button></section><div class="review-notice"><span>☆</span><p>참여 기업을 확인하고, 관심 있는 기업은 기업명 왼쪽의 별표로 표시할 수 있습니다.</p></div><section class="review-company-panel" id="review-company-list"><header><h2>${companies.length?`참여 기업 ${companies.length}개사`:"참여 기업 예시"}</h2><p>${companies.length?"기업명을 클릭하면 기업 정보를 확인할 수 있습니다.":"별표를 눌러 관심 기업 표시를 체험해 보세요. 실제 참여 기업이 등록되면 예시는 자동으로 사라집니다."}</p></header><div class="review-table"><div class="review-table-head"><span>No.</span><span>관심 기업 / 기업명 / 분야</span><span>IR 자료</span><span>투자 라운드</span><span>심사평</span><span></span></div>${rows||exampleRows}</div></section></div>`
}
function renderInvestorFeedback(){
  const items=db.meetings.filter(m=>m.type==="포켓데이").map(joined).filter(m=>m.company).sort((a,b)=>b.date.localeCompare(a.date));
  const completed=items.filter(m=>String(m.reviewComment||m.review||"").trim()).length;
  const rows=items.map((m,index)=>{const hasReview=Boolean(String(m.reviewComment||m.review||"").trim());return `<div class="review-row"><span class="review-no">${String(index+1).padStart(2,"0")}</span><button class="review-company-cell" data-company="${m.companyId}"><i class="review-company-logo logo-${index%5}">${initials(m.company.name)}</i><span><strong>${esc(m.company.name)}</strong><small>${esc(m.company.sector||"분야 미등록")} · ${esc(m.date)}</small></span></button><span class="review-stage">${esc(m.type)}</span><span class="review-stage">${esc(m.investmentStatus||"검토 전")}</span><span class="review-status ${hasReview?"done":""}">${hasReview?"작성 완료":"미작성"}</span><button class="review-open" data-go="investorReview" aria-label="${esc(m.company.name)} 심사 관리로 이동">›</button></div>`}).join("");
  return `<div class="role-dashboard investor-dashboard investor-review-page"><header class="review-page-title"><div><span>INVESTOR FEEDBACK</span><h1>심사평</h1><p>포켓데이 참여 기업별 심사평 작성 여부와 투자 검토 상태를 확인하세요.</p></div><span class="review-role-chip">작성 ${completed}건 · 미작성 ${Math.max(0,items.length-completed)}건</span></header><div class="review-notice"><span>✎</span><p>심사평 작성이 필요한 기업은 오른쪽 화살표를 눌러 심사 관리 화면으로 이동할 수 있습니다.</p></div><section class="review-company-panel"><header><h2>기업별 심사평</h2><p>최근 포켓데이 참여 순서로 표시됩니다.</p></header><div class="review-table"><div class="review-table-head"><span>No.</span><span>기업명 / 분야</span><span>구분</span><span>투자 상태</span><span>심사평</span><span></span></div>${rows||`<div class="empty">등록된 심사평 대상 기업이 없습니다.</div>`}</div></section></div>`
}

function pocketdayInvestorDetails(value=""){
  const raw=String(value).replace(/\s+/g," ").trim();
  const name=raw.match(/^([가-힣A-Za-z]+)(?=\s|\()/)?.[1]||raw;
  let firm=raw.slice(name.length).trim();
  firm=firm.replace(/^(대표|부대표|이사|팀장|매니저|심사역|책임심사역)\s*-\s*/,"");
  firm=firm.replace(/\s+-\s+\[[^\]]+\].*$/,"").trim();
  if(firm.startsWith("(")&&!firm.startsWith("(주)")){
    const close=firm.indexOf(")");
    if(close>0)firm=firm.slice(1,close).trim();
  }else{
    const detailStart=firm.indexOf("(");
    if(detailStart>2)firm=firm.slice(0,detailStart).trim();
  }
  return {name,firm};
}
function companyWorkspaceData(company){
  const profile={email:company.email||"—",phone:company.phone||"—",founded:company.founded||"—",tips:company.tips||"—",venture:company.venture||"—",smallBusiness:company.smallBusiness||"—"};
  const history=db.meetings.filter(meeting=>meeting.companyId===company.id).map(joined).filter(meeting=>meeting.investor).sort((a,b)=>b.date.localeCompare(a.date)).map((meeting,index,items)=>({round:`${items.length-index}차`,title:meeting.type||"투자 미팅",date:meeting.date||"—",place:meeting.investor?`${meeting.investor.name} · ${meeting.investor.firm||"소속 정보 없음"}`:"—",memo:meeting.memo||"등록된 메모가 없습니다.",status:meeting.followupStatus||meeting.investmentStatus||"—",tone:["예정","진행 중"].includes(meeting.followupStatus)?"purple":"mint"}));
  const companyKey=normalizeCompanyName(company.name);
  const pocketdays=pocketdaySchedule.filter(event=>(event.companies||[]).some(name=>normalizeCompanyName(name)===companyKey)||(company.pocketdayIds||[]).includes(event.id)).map(event=>({round:event.round,id:event.id,date:event.date,role:"참여 기업",status:event.status==="완료"?"참여 완료":"참여 예정",investors:(event.investors||[]).map(pocketdayInvestorDetails)}));
  return {profile,history,pocketdays,irFiles:company.irFiles||[]};
}
function renderCompanyWorkspace(company,{admin=false}={}){
  if(!company)return `<div class="panel empty">등록된 기업이 없습니다.</div>`;
  const a=companyAgg(company);const {profile,history,pocketdays,irFiles}=companyWorkspaceData(company);
  const tags=[company.stage,company.sector].filter(Boolean).map(value=>`<span>${esc(value)}</span>`).join("");
  return `<div class="role-dashboard investor-dashboard investor-meeting-page company-detail-page">${admin?`<button class="investor-detail-back" data-go="companies">← 기업 목록</button>`:`<nav class="meeting-breadcrumb"><span>심사역</span><b>›</b><span>${esc(company.name)}</span><b>›</b><strong>미팅 관리</strong></nav>`}<section class="company-meeting-hero"><div class="meeting-company-brand"><div class="meeting-company-logo">${initials(company.name)}</div><div><span class="meeting-kicker">COMPANY DETAIL</span><h1>${esc(company.name)}</h1><p>${esc(company.description||"기업 정보를 입력해 주세요.")}</p><div class="meeting-tags">${tags}</div></div></div><div class="company-info-grid"><div><i>♙</i><span><small>대표자</small><strong>${company.ceo?`${esc(company.ceo)} 대표`:"—"}</strong></span></div><div><i>▣</i><span><small>설립일 / 업력</small><strong>${esc(profile.founded)}</strong></span></div><div><i>✉</i><span><small>이메일</small><strong>${esc(profile.email)}</strong></span></div><div><i>⌕</i><span><small>연락처</small><strong>${esc(profile.phone)}</strong></span></div><div><i>▤</i><span><small>팁스 선정 여부</small><strong class="${profile.tips==="선정"?"info-approved":"info-pending"}">${esc(profile.tips)}</strong></span></div><div><i>♙</i><span><small>벤처기업 인증</small><strong class="${profile.venture==="인증"?"info-approved":"info-pending"}">${esc(profile.venture)}</strong></span></div><div><i>▥</i><span><small>기업 형태</small><strong>${esc(profile.smallBusiness)}</strong></span></div><div><i>▥</i><span><small>투자 유치 단계</small><strong>${esc(company.stage||"—")}</strong></span></div><div><i>₩</i><span><small>기업 밸류</small><strong>${esc(company.valuation||"—")}</strong></span></div></div><div class="company-hero-actions">${admin?`<button class="outline-action" data-edit-company="${company.id}">정보 수정</button><button class="company-delete-button" data-delete-company="${company.id}">기업 삭제</button>`:""}<button class="meeting-request-button" data-open-meeting>＋ 미팅 추가 요청</button></div></section><div class="company-detail-workspace"><section class="meeting-history-panel"><header><div><h2>미팅 이력</h2><p>${esc(company.name)}과 진행한 모든 미팅을 확인할 수 있습니다.</p></div><span>${a.ms.length} meetings</span></header><div class="meeting-timeline compact">${history.map((item,index)=>`<article class="timeline-item ${item.tone}"><div class="timeline-marker"><span></span></div><div class="timeline-round"><strong>${item.round}</strong><small>미팅</small></div><div class="timeline-copy"><div><h3>${esc(item.title)}</h3><span class="timeline-status ${item.status==="완료"?"done":""}">${esc(item.status)}</span></div><p>▣ ${esc(item.date)}</p><p>⌖ ${esc(item.place)}</p><em>${esc(item.memo)}</em></div><button class="timeline-detail" data-meeting-detail="${index}">상세 보기 ›</button><button class="timeline-more" aria-label="더 보기">⋮</button></article>`).join("")||`<div class="empty">등록된 미팅 이력이 없습니다.</div>`}</div></section><section class="pocketday-panel"><header><div><h2>포켓데이 참여 이력</h2><p>${esc(company.name)}의 포켓데이 참여 기록입니다.</p></div><span>${pocketdays.length}회</span></header><div class="pocketday-detail-list">${pocketdays.map(item=>`<article><div class="pocketday-round"><strong>제${item.round}회</strong><span>${esc(item.id)}</span></div><div><time>${esc(item.date)}</time><h3>${esc(item.role)}</h3><p>참여 심사역 ${item.investors.length}명</p></div><span class="timeline-status ${item.status==="참여 완료"?"done":""}">${esc(item.status)}</span></article>`).join("")||`<div class="empty">포켓데이 참여 이력이 없습니다.</div>`}</div></section><section class="ir-files-panel"><header><div><h2>IR 자료</h2><p>${esc(company.name)}의 투자 검토 자료를 확인합니다.</p></div><button data-add-ir>＋ 자료 추가</button></header><div class="ir-file-list">${irFiles.map((file,index)=>`<article><i class="file-type file-${esc(file.type||"file").toLowerCase()}">${esc(file.type||"FILE")}</i><div><strong>${esc(file.name)}</strong><span>${esc(file.meta)}</span></div><button data-ir-file="${index}" aria-label="${esc(file.name)} 열기">↓</button></article>`).join("")||`<div class="empty">등록된 IR 자료가 없습니다.</div>`}</div></section><section class="pocketday-investor-panel"><header><div><h2>포켓데이 참여 심사역</h2><p>회차별로 만난 심사역과 소속 투자사를 확인합니다.</p></div><span>${pocketdays.reduce((total,item)=>total+item.investors.length,0)}명</span></header><div class="pocketday-investor-history">${pocketdays.map(item=>`<article><div class="pocketday-investor-event"><strong>제${item.round}회</strong><span>${esc(item.id)} · ${esc(item.date)}</span></div><div class="pocketday-investor-list">${item.investors.map(investor=>`<div><i>${initials(investor.name)}</i><span><strong>${esc(investor.name)}</strong><small>${esc(investor.firm||"—")}</small></span></div>`).join("")||`<em>참여 심사역 정보가 없습니다.</em>`}</div></article>`).join("")||`<div class="empty">포켓데이 참여 이력이 없습니다.</div>`}</div></section></div></div>`;
}
function renderInvestorMeetings(){return renderCompanyWorkspace(com(selectedInvestorCompanyId)||activeCompanies()[0])}
function renderCompanyDetail(){const company=com(selectedCompanyId);if(!company||company.deletedAt)return `<button class="investor-detail-back" data-go="companies">← 기업 목록</button><div class="panel empty">삭제된 기업입니다. 기존 포켓데이와 미팅 이력은 각 이력 화면에 유지됩니다.</div>`;return renderCompanyWorkspace(company,{admin:true})}

function stat(label,value,foot,icon,tone){return `<article class="stat-card"><header><span>${label}</span><i style="--tone:${tone}">${icon}</i></header><div class="stat-value">${value}</div><p>${foot}</p></article>`}

function renderPipeline(data,full=false){const statuses=full?statusOrder:statusOrder.slice(0,4);return `<div class="pipeline ${full?'full':''}">${statuses.map(s=>{const items=data.filter(m=>m.investmentStatus===s);return `<section class="pipe-col"><div class="pipe-title"><span>${s}</span><b>${items.length}</b></div>${items.map(m=>`<article class="pipe-card"><button data-company="${m.companyId}">${esc(m.company.name)}</button><span>${esc(m.investor.name)} · ${esc(m.investor.firm)}</span><footer><span>${fmtDate(m.date)}</span><b>${fmtMoney(m.amount)}</b></footer></article>`).join("")||`<div class="empty" style="padding:25px 2px">기록 없음</div>`}</section>`}).join("")}</div>`}
function renderAgenda(data){const items=data.filter(m=>["예정","진행 중"].includes(m.followupStatus)).sort((a,b)=>(a.followupDate||"9999").localeCompare(b.followupDate||"9999")).slice(0,4);return `<div class="agenda">${items.map(m=>{const d=new Date(m.followupDate);return `<article class="agenda-item"><div class="date-box"><strong>${d.getDate()}</strong><span>${d.getMonth()+1}월</span></div><div><button class="link-button" data-company="${m.companyId}">${esc(m.company.name)}</button><p><button class="entity-link" data-investor="${m.investorId}">${esc(m.investor.name)}</button> · ${esc(m.investor.firm)}</p></div>${badge(overdue(m)?"기한 지남":m.followupStatus,overdue(m)?"overdue":"scheduled")}</article>`}).join("")||`<div class="empty">예정된 후속 미팅이 없습니다.</div>`}</div>`}
function meetingRows(data,editable=false){if(!data.length)return `<tr><td colspan="${editable?8:9}"><div class="empty">조건에 맞는 미팅이 없습니다.</div></td></tr>`;const rows=data.sort((a,b)=>b.date.localeCompare(a.date));if(editable)return rows.map(m=>`<tr><td>${fmtDate(m.date)}</td><td><div class="entity-cell"><i class="entity-mark">${initials(m.company.name)}</i><div><button class="entity-link" data-company="${m.companyId}">${esc(m.company.name)}</button><small>${esc(m.company.sector)}</small></div></div></td><td><button class="entity-link" data-investor="${m.investorId}">${esc(m.investor.name)}</button></td><td>${esc(m.investor.firm||"—")}</td><td><select class="status-select" data-followup-id="${m.id}">${["미정","예정","진행 중","완료","없음"].map(s=>`<option ${s===m.followupStatus?'selected':''}>${s}</option>`).join("")}</select></td><td><select class="status-select" data-status-id="${m.id}">${statusOrder.map(s=>`<option ${s===m.investmentStatus?'selected':''}>${s}</option>`).join("")}</select></td><td>${fmtMoney(m.amount)}</td><td><select class="status-select payment-select" data-payment-id="${m.id}"><option ${(!m.paymentStatus||m.paymentStatus==="미지급")?'selected':''}>미지급</option><option ${m.paymentStatus==="지급"?'selected':''}>지급</option></select></td></tr>`).join("");return rows.map(m=>`<tr><td><div class="entity-cell"><i class="entity-mark">${initials(m.company.name)}</i><div><button class="entity-link" data-company="${m.companyId}">${esc(m.company.name)}</button><small>${esc(m.company.sector)}</small></div></div></td><td><button class="entity-link" data-investor="${m.investorId}">${esc(m.investor.name)}</button><br><small style="color:var(--muted)">${esc(m.investor.firm)}</small></td><td>${fmtDate(m.date)}</td><td>${esc(m.type)}</td><td>${badge(m.investmentStatus)}</td><td>${badge(overdue(m)?"기한 지남":m.followupStatus,overdue(m)?"overdue":"")}</td><td>${fmtDate(m.followupDate)}</td><td>${fmtMoney(m.amount)}</td><td>${fmtDate(m.updatedAt)}</td></tr>`).join("")}
function meetingTable(data,title="미팅 이력",editable=false){const headers=editable?["포켓데이 날짜","기업","심사역","투자사","후속 상태","투자 상태","투자금액","지급"]:["기업","심사역","미팅일","구분","투자 상태","후속 상태","후속 예정일","투자금액","최근 업데이트"];return `<section class="panel table-panel"><div class="table-toolbar"><div><strong>${title}</strong><span>${data.length}개 기록</span></div>${currentView==='dashboard'?`<button class="text-button" data-go="meetings">전체 보기 →</button>`:""}</div><div class="table-wrap"><table><thead><tr>${headers.map(header=>`<th>${header}</th>`).join("")}</tr></thead><tbody>${meetingRows(data,editable)}</tbody></table></div></section>`}

function renderDashboard(data){const reviewing=data.filter(m=>["검토 전","검토 중","투자 확정"].includes(m.investmentStatus)).length;const follow=data.filter(m=>["예정","진행 중"].includes(m.followupStatus)).length;const done=data.filter(m=>m.investmentStatus==="투자 완료");return `<div class="stats-grid">${stat("전체 미팅 이력",data.length,"심사역 × 기업 관계 기준","▦","#dfeee5")}${stat("투자 검토 중",reviewing,"검토 전·검토 중·투자 확정","◔","#e7eef6")}${stat("후속 미팅 예정",follow,"미팅 이력에서 자동 집계","↗","#fff0cf")}${stat("투자 완료",done.length,`${fmtMoney(done.reduce((a,b)=>a+b.amount,0))} 누적`,"✓","#dff28a")}</div><div class="overview-grid"><section class="panel"><div class="panel-head"><div><h2>투자 파이프라인</h2><p>미팅 이력 DB의 투자 진행 상태별 보기</p></div><button class="text-button" data-go="pipeline">전체 보기 →</button></div>${renderPipeline(data)}</section><section class="panel"><div class="panel-head"><div><h2>다가오는 후속 미팅</h2><p>미팅 이력 DB의 후속 일정 보기</p></div><button class="text-button" data-go="followups">전체 보기 →</button></div>${renderAgenda(data)}</section></div>${meetingTable(data.slice(0,5),"최근 미팅 이력")}`}
function renderMeetings(data){return `<div class="list-header"><p>이 DB의 한 행이 기업과 심사역의 한 번의 미팅 관계입니다.</p><button class="primary-button" data-open-meeting>＋ 기록 추가</button></div>${meetingTable(data,"미팅 이력 데이터베이스",true)}`}

function investorAgg(person){const ms=db.meetings.filter(m=>m.investorId===person.id).map(joined).filter(m=>m.company);return {ms,companies:new Set(ms.map(m=>m.companyId)).size,review:ms.filter(m=>["검토 전","검토 중","투자 확정"].includes(m.investmentStatus)).length,followups:ms.filter(m=>["예정","진행 중"].includes(m.followupStatus)).length,done:ms.filter(m=>m.investmentStatus==="투자 완료").length,latest:ms.map(m=>m.date).sort().at(-1)||""}}
function renderInvestors(){const people=db.investors.filter(p=>{const a=investorAgg(p);return match(p.name,p.firm,p.operatorType,p.title,p.focus.join(" "),...a.ms.flatMap(m=>[m.company?.name,m.memo]))});return `<div class="list-header"><p>직접 등록한 심사역의 기본 정보와 연결된 이력을 관리합니다.</p><button class="primary-button" data-open-investor>＋ 심사역 추가</button></div><section class="panel db-table"><div class="table-wrap"><table><thead><tr><th>심사역</th><th>소속 투자사 · 운영사 종류</th><th>직책</th><th>관심 분야</th><th>후속 미팅</th><th>투자 완료</th></tr></thead><tbody>${people.map(p=>{const a=investorAgg(p);const operatorType=p.operatorType||operatorTypeForFirm(p.firm);return `<tr><td><div class="entity-cell"><i class="entity-mark">${initials(p.name)}</i><div><button class="entity-link" data-investor="${p.id}">${esc(p.name)}</button>${p.email?`<small>${esc(p.email)}</small>`:""}${p.phone?`<small>연락처 ${esc(p.phone)}</small>`:""}</div></div></td><td><div class="firm-with-type">${p.firm?`<span>${esc(p.firm)}</span>`:""}${operatorTypeBadges(operatorType)}</div></td><td>${esc(p.title)}</td><td><div class="focus-tags">${p.focus.map(x=>`<span class="tag">${esc(x)}</span>`).join("")}</div></td><td>${a.followups}</td><td>${a.done}</td></tr>`}).join("")||`<tr><td colspan="6"><div class="empty investor-empty"><strong>등록된 심사역이 없습니다.</strong><span>심사역 추가 버튼을 눌러 직접 등록해 주세요.</span><button class="primary-button" data-open-investor>＋ 첫 심사역 추가</button></div></td></tr>`}</tbody></table></div></section>`}
function companyAgg(company){const ms=db.meetings.filter(m=>m.companyId===company.id).map(joined);return {ms,investors:new Set(ms.map(m=>m.investorId)).size,active:ms.filter(m=>["검토 중","투자 확정"].includes(m.investmentStatus)).length,latest:ms.map(m=>m.date).sort().at(-1)||""}}
function renderCompanies(statusFilter=""){const remaining=companyRemainingRoundMap();const active=activeCompanies();const inProgress=statusFilter==="진행중";const completed=statusFilter==="완료";const inProgressCount=active.filter(company=>remaining[company.id]==="진행중").length;const completedCount=active.filter(company=>remaining[company.id]==="완료").length;const companies=active.filter(c=>{const a=companyAgg(c);const searchMatch=match(c.name,c.ceo,c.sector,c.stage,c.description,...a.ms.flatMap(m=>[m.investor?.name,m.investor?.firm,m.memo]));return searchMatch&&(!statusFilter||remaining[c.id]===statusFilter)});const description=inProgress?"잔여회차가 진행중인 기업만 모아봅니다.":completed?"잔여회차가 완료된 기업만 모아봅니다.":"기업을 기준으로 연결된 투자사와 심사역 접점을 확인합니다.";const countLabel=inProgress?`진행중 ${inProgressCount}개사`:completed?`완료 ${completedCount}개사`:"관계형 보기";const emptyLabel=inProgress?"진행중인 기업이 없습니다.":completed?"완료된 기업이 없습니다.":"조건에 맞는 기업이 없습니다.";return `<div class="company-list-tabs" role="tablist" aria-label="기업 목록 구분"><button type="button" role="tab" aria-selected="${!statusFilter}" class="${!statusFilter?"active":""}" data-company-list-view="companies">전체 기업 <b>${active.length}</b></button><button type="button" role="tab" aria-selected="${inProgress}" class="${inProgress?"active":""}" data-company-list-view="companiesInProgress">진행중 기업 <b>${inProgressCount}</b></button><button type="button" role="tab" aria-selected="${completed}" class="${completed?"active":""}" data-company-list-view="companiesCompleted">완료 기업 <b>${completedCount}</b></button></div><div class="list-header"><p>${description}</p><div class="list-header-actions"><span class="badge ${completed?"completed":inProgress?"scheduled":"confirmed"}">${countLabel}</span><button class="primary-button" data-add-company>＋ 기업 직접 추가</button></div></div><section class="panel db-table"><div class="table-wrap"><table><thead><tr><th>기업</th><th>대표자</th><th>업종</th><th>단계</th><th>미팅</th><th>만난 심사역</th></tr></thead><tbody>${companies.map(c=>{const a=companyAgg(c);return `<tr><td><div class="entity-cell"><i class="entity-mark">${initials(c.name)}</i><div><button class="entity-link" data-company="${c.id}">${esc(c.name)}</button><small>${esc(c.description)}</small></div></div></td><td>${esc(c.ceo)}</td><td><span class="tag">${esc(c.sector)}</span></td><td>${esc(c.stage)}</td><td>${a.ms.length}</td><td>${a.investors}</td></tr>`}).join("")||`<tr><td colspan="6"><div class="empty">${emptyLabel}</div></td></tr>`}</tbody></table></div></section>`}
function renderHouses(){const headers=["투자사","투자사 종류","운영사 종류","주요 투자 섹터","이메일","메모"];const rows=(window.housesSeed||[]).filter(row=>match(...row));return `<div class="list-header"><p>구글시트의 하우스 탭 목록을 원본 순서와 표기 그대로 표시합니다.</p><span class="badge confirmed">${rows.length}개 하우스</span></div><section class="panel db-table house-table-panel"><div class="table-wrap"><table class="house-table"><thead><tr>${headers.map(header=>`<th>${header}</th>`).join("")}</tr></thead><tbody>${rows.map(row=>`<tr>${headers.map((_,index)=>`<td>${esc(row[index]??"")}</td>`).join("")}</tr>`).join("")||`<tr><td colspan="6"><div class="empty">표시할 하우스가 없습니다.</div></td></tr>`}</tbody></table></div></section>`}
function renderAnnualLinkage(){const years=[2026,2025,2024];const items=db.meetings.map(joined).filter(m=>m.date.startsWith(`${annualYear}-`));const matched=items.filter(m=>["예정","진행 중","완료"].includes(m.followupStatus)).length;const matchRate=items.length?Math.round(matched/items.length*100):0;const completed=items.filter(m=>m.investmentStatus==="투자 완료");const reviewing=items.filter(m=>["검토 전","검토 중","투자 확정"].includes(m.investmentStatus)).length;const invested=completed.reduce((sum,m)=>sum+m.amount,0);const monthly=Array.from({length:12},(_,index)=>items.filter(m=>Number(m.date.slice(5,7))===index+1).length);const maxMonthly=Math.max(1,...monthly);const statusSummary=statusOrder.map(status=>({status,count:items.filter(m=>m.investmentStatus===status).length})).filter(x=>x.count);const rows=items.sort((a,b)=>b.date.localeCompare(a.date)).map(m=>`<tr><td>${fmtDate(m.date)}</td><td><button class="entity-link" data-company="${m.companyId}">${esc(m.company.name)}</button></td><td><button class="entity-link" data-investor="${m.investorId}">${esc(m.investor.name)}</button><small>${esc(m.investor.firm)}</small></td><td>${badge(m.followupStatus)}</td><td>${badge(m.investmentStatus)}</td><td>${fmtMoney(m.amount)}</td></tr>`).join("");return `<div class="annual-linkage-page"><section class="annual-dashboard-head"><div><span>INVESTMENT LINKAGE DASHBOARD</span><h2>${annualYear}년 투자 연계 대시보드</h2></div><div class="annual-year-tabs" aria-label="연도 선택">${years.map(year=>`<button class="${annualYear===year?"active":""}" data-annual-year="${year}" aria-pressed="${annualYear===year}">${year}</button>`).join("")}</div></section><section class="annual-summary-grid"><article><span>전체 투자 연계</span><strong>${items.length}<em>건</em></strong><p>기업·심사역 미팅 기준</p><i>◎</i></article><article><span>후속 미팅 매칭률</span><strong>${matchRate}<em>%</em></strong><p>${items.length?`${matched}/${items.length}건 후속 연결`:"등록된 연계 없음"}</p><i>↗</i></article><article><span>투자 검토 진행</span><strong>${reviewing}<em>건</em></strong><p>검토 전·검토 중·확정</p><i>◔</i></article><article><span>투자 완료</span><strong>${completed.length}<em>건</em></strong><p>${invested?`${fmtMoney(invested)} 누적`:"집계된 금액 없음"}</p><i>✓</i></article></section><div class="annual-insight-grid"><section class="panel annual-chart-panel"><header><div><span>MONTHLY LINKAGE</span><h2>월별 투자 연계 추이</h2></div><strong>${annualYear}</strong></header><div class="annual-bar-chart">${monthly.map((count,index)=>{const height=count?Math.max(18,Math.round(count/maxMonthly*100)):3;return `<div class="annual-bar"><div><i style="height:${height}%"></i><b style="bottom:${Math.min(94,height+3)}%">${count||""}</b></div><span>${index+1}월</span></div>`}).join("")}</div></section><section class="panel annual-conversion-panel"><header><span>CONVERSION</span><h2>후속 미팅 전환</h2></header><div class="annual-gauge" style="--rate:${matchRate*3.6}deg"><div><strong>${matchRate}%</strong><span>매칭률</span></div></div><div class="annual-status-list">${statusSummary.length?statusSummary.map(x=>`<div><span>${esc(x.status)}</span><strong>${x.count}건</strong></div>`).join(""):`<p class="annual-empty-status">해당 연도의 투자 상태 기록이 없습니다.</p>`}</div></section></div><section class="panel annual-linkage-table"><header><div><span>${annualYear} CONNECTIONS</span><h2>투자 연계 상세</h2></div><p>미팅 이력 DB와 자동 연결된 연간 현황입니다.</p></header><div class="table-wrap"><table><thead><tr><th>일자</th><th>기업</th><th>심사역 / 투자사</th><th>후속 미팅</th><th>투자 상태</th><th>투자 금액</th></tr></thead><tbody>${rows||`<tr><td colspan="6"><div class="empty">${annualYear}년 투자 연계 기록이 없습니다.</div></td></tr>`}</tbody></table></div></section></div>`}
function renderFollowups(data){const items=data.filter(m=>["예정","진행 중"].includes(m.followupStatus)).sort((a,b)=>(a.followupDate||"9999").localeCompare(b.followupDate||"9999"));return `<div class="followup-grid">${items.map(m=>`<article class="panel followup-card"><header>${badge(overdue(m)?"기한 지남":m.followupStatus,overdue(m)?"overdue":"scheduled")}<span style="font-size:8px;color:var(--muted)">${fmtDate(m.followupDate)}</span></header><h2><button class="entity-link" data-company="${m.companyId}">${esc(m.company.name)}</button></h2><p>${esc(m.memo||"등록된 다음 액션이 없습니다.")}</p><footer><button class="entity-link" data-investor="${m.investorId}">${esc(m.investor.name)} · ${esc(m.investor.firm)}</button>${badge(m.investmentStatus)}</footer></article>`).join("")||`<div class="panel empty">예정된 후속 미팅이 없습니다.</div>`}</div>`}

function pocketdayLabel(event){return event.round?`제${event.round}회`:event.id}
function pocketdayOperationType(event){return event.operationType||"포켓데이"}
function refreshOperationTypeOptions(selected="포켓데이"){const select=document.getElementById("pocketdayOperationType");if(!select)return;select.innerHTML=pocketdayOperationTypes.map(type=>`<option value="${esc(type)}">${esc(type)}</option>`).join("");select.value=pocketdayOperationTypes.includes(selected)?selected:"포켓데이"}
function renderPocketdaySchedule(){
  const searchTerm=query.trim();
  const years=[...new Set(pocketdaySchedule.map(event=>Number(String(event.date||"").match(/\d{4}/)?.[0])).filter(Boolean))].sort((a,b)=>b-a);
  if(!pocketdayYear||!years.includes(pocketdayYear))pocketdayYear=years[0]||new Date().getFullYear();
  const yearEvents=pocketdaySchedule.filter(event=>Number(String(event.date||"").match(/\d{4}/)?.[0])===pocketdayYear);
  const visibleEvents=yearEvents.filter(event=>match(event.id,event.round,pocketdayLabel(event),event.date,pocketdayOperationType(event),event.status,...(event.companies||[]),...(event.investors||[])));
  const next=visibleEvents.find(event=>event.status==="예정");
  const completed=yearEvents.filter(event=>event.status==="완료").length;
  const rows=visibleEvents.map(event=>`<article><div class="pocketday-schedule-round"><small>${esc(event.id)}</small><strong>${esc(pocketdayLabel(event))}</strong></div><div class="pocketday-schedule-info"><h3>${esc(event.date)}</h3><p>운영구분 · ${esc(pocketdayOperationType(event))}</p></div><div class="pocketday-schedule-companies"><div>${event.companies.map(name=>`<span>${esc(name)}</span>`).join("")}</div><details class="pocketday-schedule-investors"><summary>참여 심사역 ${(event.investors||[]).length}명</summary><ul>${(event.investors||[]).map(name=>`<li>${esc(name)}</li>`).join("")}</ul></details></div><span class="pocketday-schedule-status ${event.status==="완료"?"done":"upcoming"}">${esc(event.status)}</span><button class="pocketday-edit-button" data-edit-pocketday="${esc(event.id)}">수정</button></article>`).join("");
  return `<div class="pocketday-admin-page"><div class="pocketday-year-tabs" aria-label="포켓데이 일정 연도 선택">${years.map(year=>`<button class="${year===pocketdayYear?"active":""}" data-pocketday-year="${year}" aria-pressed="${year===pocketdayYear}">${year}년</button>`).join("")}</div>${next?`<section class="pocketday-next-card"><div class="pocketday-next-icon">▣</div><div class="pocketday-next-copy"><span>NEXT POCKET DAY</span><h2>${esc(next.date)}</h2><p><strong>${esc(pocketdayLabel(next))}</strong><i>·</i>${esc(pocketdayOperationType(next))}</p><div>${next.companies.map(name=>`<em>${esc(name)}</em>`).join("")}</div></div><span class="pocketday-schedule-status upcoming">예정</span></section>`:""}<section class="pocketday-schedule-summary"><article><span>${pocketdayYear}년 전체 일정</span><strong>${yearEvents.length}<em>회</em></strong></article><article><span>예정</span><strong>${yearEvents.length-completed}<em>회</em></strong></article><article><span>완료</span><strong>${completed}<em>회</em></strong></article></section><section class="panel pocketday-schedule-panel"><header><div><span>${pocketdayYear} ARCHIVE</span><h2>${pocketdayYear}년 포켓데이 일정</h2></div><div class="pocketday-schedule-actions"><p>선택한 연도의 일정을 최신순으로 표시합니다.</p><button class="primary-button" data-add-pocketday>＋ 일정 추가</button></div></header>${searchTerm?`<div class="pocketday-filter-result"><span>⌕</span><strong>‘${esc(searchTerm)}’ 검색 결과</strong><b>${visibleEvents.length}회</b></div>`:""}<div class="pocketday-schedule-list">${rows||`<div class="pocketday-schedule-empty"><strong>${pocketdayYear}년 일정이 없습니다.</strong><p>다른 연도를 선택하거나 새 일정을 추가해 주세요.</p></div>`}</div></section></div>`;
}

function openPocketdayModal(id=""){const form=document.getElementById("pocketdayForm");const event=id?pocketdaySchedule.find(item=>item.id===id):null;form.reset();document.getElementById("operationTypeAdd").hidden=true;form.elements.eventId.value=event?.id||"";form.elements.round.value=event?.round||"";form.elements.date.value=event?.date||"";refreshOperationTypeOptions(pocketdayOperationType(event||{}));form.elements.status.value=event?.status||"예정";form.elements.companies.value=(event?.companies||[]).join(", ");form.elements.investors.value=(event?.investors||[]).join("\n");document.getElementById("pocketdayModalTitle").textContent=event?`${pocketdayLabel(event)} 포켓데이 수정`:"포켓데이 일정 추가";document.getElementById("pocketdaySubmitLabel").textContent=event?"수정 내용 저장":"새 일정 저장";document.getElementById("pocketdayModal").hidden=false;setTimeout(()=>form.elements.round.focus(),0)}
function closePocketdayModal(){document.getElementById("pocketdayModal").hidden=true;document.getElementById("operationTypeAdd").hidden=true;document.getElementById("operationTypeName").value=""}
function addPocketdayOperationType(){const input=document.getElementById("operationTypeName");const name=input.value.trim();if(!name){showToast("추가할 카테고리명을 입력해 주세요.");input.focus();return}const existing=pocketdayOperationTypes.find(type=>type.toLowerCase()===name.toLowerCase());if(existing){refreshOperationTypeOptions(existing);showToast("이미 등록된 카테고리입니다.")}else{pocketdayOperationTypes.push(name);savePocketdayOperationTypes();refreshOperationTypeOptions(name);showToast(`${name} 카테고리를 추가했습니다.`)}input.value="";document.getElementById("operationTypeAdd").hidden=true}

function openInvestor(id){selectedInvestorId=id;switchView("investorDetail")}
function investorPocketdayConnections(person){
  return pocketdaySchedule.filter(event=>(event.investors||[]).some(value=>pocketdayInvestorDetails(value).name===person.name)).sort((a,b)=>b.date.localeCompare(a.date)).map(event=>({id:event.id,round:event.round,date:event.date,status:event.status==="완료"?"참여 완료":"참여 예정",companies:[...new Set((event.companies||[]).map(cleanImportedCompanyName).filter(Boolean))]}));
}
function researchKey(investorId,companyId="",companyName=""){return `${investorId}::${companyId||normalizeCompanyName(companyName)}`}
function investorResearchCompanies(person,connections){
  const map=new Map();
  connections.forEach(event=>event.companies.forEach(name=>{const normalized=normalizeCompanyName(name);if(!normalized)return;const company=db.companies.find(item=>normalizeCompanyName(item.name)===normalized);if(!map.has(normalized))map.set(normalized,{name,company,eventIds:[]});const item=map.get(normalized);if(!item.eventIds.includes(event.id))item.eventIds.push(event.id)}));
  return [...map.values()];
}
function researchRecord(investorId,companyId="",companyName=""){
  const key=researchKey(investorId,companyId,companyName);
  const stored=db.connectionResearch[key];
  if(stored)return {followupStatus:"미확인",investmentStatus:"모니터링",checkedAt:"",source:"",memo:"",...stored,investmentStatus:normalizeResearchInvestmentStatus(stored.investmentStatus),key};
  const related=db.meetings.filter(meeting=>meeting.investorId===investorId&&(companyId?meeting.companyId===companyId:normalizeCompanyName(com(meeting.companyId)?.name)===normalizeCompanyName(companyName))).sort((a,b)=>b.date.localeCompare(a.date));
  const latest=related[0];
  return {key,investorId,companyId,companyName,followupStatus:latest?.followupStatus||"미확인",investmentStatus:"미확인",checkedAt:latest?.updatedAt||"",source:latest?"미팅 이력":"",memo:latest?.memo||""};
}
const researchInvestmentOptions=["-","미확인","모니터링","미팅","진행중","투자완료","보육중"];
function normalizeResearchInvestmentStatus(value=""){
  return researchInvestmentOptions.includes(value)?value:"미확인";
}
function researchMeetingStatuses(record){
  const investmentStatus=({"-":"검토 전","미확인":"검토 전","모니터링":"검토 전","미팅":"검토 중","진행중":"투자 확정","투자완료":"투자 완료","보육중":"투자 완료"})[normalizeResearchInvestmentStatus(record.investmentStatus)]||"검토 전";
  return {followupStatus:record.followupStatus==="미확인"?"미정":record.followupStatus,investmentStatus};
}
function latestPocketdayMeeting(investorId,companyName){
  const person=inv(investorId);
  const normalizedCompany=normalizeCompanyName(companyName);
  return pocketdaySchedule.filter(event=>(event.investors||[]).some(value=>pocketdayInvestorDetails(value).name===person?.name)&&(event.companies||[]).some(value=>normalizeCompanyName(value)===normalizedCompany)).sort((a,b)=>b.date.localeCompare(a.date))[0];
}
function syncResearchToMeeting(record){
  record.investmentStatus=normalizeResearchInvestmentStatus(record.investmentStatus);
  const isBlankResearch=record.followupStatus==="미확인"&&!record.investmentStatus&&!String(record.memo||"").trim();
  if(isBlankResearch){
    db.meetings=db.meetings.filter(meeting=>!(meeting.source==="만난 기업 후속 현황"&&meeting.investorId===record.investorId&&(record.companyId?meeting.companyId===record.companyId:normalizeCompanyName(com(meeting.companyId)?.name)===normalizeCompanyName(record.companyName))));
    return "ignored";
  }
  let company=record.companyId?com(record.companyId):db.companies.find(item=>normalizeCompanyName(item.name)===normalizeCompanyName(record.companyName));
  const event=latestPocketdayMeeting(record.investorId,record.companyName);
  if(!company){company={id:`com-${Date.now()}`,name:record.companyName,ceo:"",sector:"",stage:"",valuation:"",description:"",email:"",phone:"",founded:"",tips:"",venture:"",smallBusiness:"",pocketdayIds:event?.id?[event.id]:[],irFiles:[]};db.companies.unshift(company)}
  const related=db.meetings.filter(meeting=>meeting.investorId===record.investorId&&meeting.companyId===company.id).sort((a,b)=>b.date.localeCompare(a.date));
  const meeting=related[0];
  const statuses=researchMeetingStatuses(record);
  if(meeting){Object.assign(meeting,statuses,{updatedAt:today(),memo:record.memo||meeting.memo||""})}
  else db.meetings.unshift({id:`mtg-research-${Date.now()}`,companyId:company.id,investorId:record.investorId,date:event?.date||today(),type:event?.operationType||"포켓데이",...statuses,followupDate:"",amount:0,paymentStatus:"미지급",updatedAt:today(),memo:record.memo||"",source:"만난 기업 후속 현황"});
  record.companyId=company.id;
  record.source="미팅 이력 자동 연결";
  return meeting?"updated":"created";
}
const researchMeetingBackfillCleanupKey="pocket-crm-research-meeting-backfill-cleanup-v1";
if(!localStorage.getItem(researchMeetingBackfillCleanupKey)){
  const remaining=db.meetings.filter(meeting=>!(meeting.source==="만난 기업 후속 현황"&&String(meeting.id).startsWith("mtg-research-")));
  if(remaining.length!==db.meetings.length){db.meetings=remaining;save()}
  localStorage.setItem(researchMeetingBackfillCleanupKey,"1");
}
const blankResearchMeetingCleanupKey="pocket-crm-blank-research-meeting-cleanup-v2";
if(!localStorage.getItem(blankResearchMeetingCleanupKey)){
  const remaining=db.meetings.filter(meeting=>!(meeting.source==="만난 기업 후속 현황"&&meeting.followupStatus==="미정"&&meeting.investmentStatus==="검토 전"&&!String(meeting.memo||"").trim()&&!meeting.followupDate&&!Number(meeting.amount||0)));
  if(remaining.length!==db.meetings.length){db.meetings=remaining;save()}
  localStorage.setItem(blankResearchMeetingCleanupKey,"1");
}
function researchNeedsCheck(record){return record.followupStatus==="미확인"||["-","미확인"].includes(record.investmentStatus)}
function researchStatusTone(value){return value==="투자완료"||value==="투자 완료"||value==="완료"?"complete":value==="보육중"?"nurture":["진행","진행중","진행 중","검토 중"].includes(value)?"progress":["예정","미팅"].includes(value)?"scheduled":value==="미확인"?"unknown":"neutral"}
function researchStatusBadge(value){return `<span class="research-status ${researchStatusTone(value)}">${esc(value||"미확인")}</span>`}
function researchInlineSelect(field,value,investorId,companyId,companyName){const normalizedValue=field==="investmentStatus"?normalizeResearchInvestmentStatus(value):value;const options=field==="followupStatus"?["미확인","없음","예정","진행 중","완료"]:researchInvestmentOptions;const label=field==="followupStatus"?"후속 미팅":"투자 상태";return `<label class="research-inline-select ${researchStatusTone(normalizedValue)}"><select data-inline-research data-field="${field}" data-investor-id="${investorId}" data-company-id="${companyId}" data-company-name="${esc(companyName)}" aria-label="${esc(companyName)} ${label}">${options.map(option=>`<option ${option===normalizedValue?"selected":""}>${option}</option>`).join("")}</select></label>`}
function renderInvestorDetail(){
  const p=inv(selectedInvestorId)||db.investors[0];
  if(!p)return `<div class="panel empty">등록된 심사역이 없습니다.</div>`;
  const a=investorAgg(p);
  const connections=investorPocketdayConnections(p);
  const uniqueCompanies=new Set(connections.flatMap(event=>event.companies.map(normalizeCompanyName))).size;
  const firm=p.firm||"미등록";const title=p.title||"미등록";const email=p.email||"미등록";const phone=p.phone||"미등록";
  const operatorType=p.operatorType||operatorTypeForFirm(p.firm);
  const profileLine=[p.firm,p.title].filter(Boolean).join(" · ")||"기본 정보 미등록";
  const focus=(p.focus||[]).length?p.focus.map(x=>`<b>${esc(x)}</b>`).join(""):`<span class="investor-info-empty">미등록</span>`;
  const connectionRows=connections.map(event=>`<article><div class="investor-pocketday-event"><strong>제${event.round}회 포켓데이</strong><span>${esc(event.id)} · ${esc(event.date)}</span><em class="${event.status==="참여 완료"?"done":""}">${esc(event.status)}</em></div><div class="investor-pocketday-companies">${event.companies.map(name=>{const company=db.companies.find(item=>normalizeCompanyName(item.name)===normalizeCompanyName(name));return company?`<button data-company="${company.id}"><i>${initials(name)}</i><span>${esc(name)}</span></button>`:`<span><i>${initials(name)}</i><b>${esc(name)}</b></span>`}).join("")||`<small>참여 기업 정보가 없습니다.</small>`}</div></article>`).join("");
  const researchCompanies=investorResearchCompanies(p,connections);
  const researchItems=researchCompanies.map(item=>({...item,record:researchRecord(p.id,item.company?.id||"",item.name)}));
  const followupCount=researchItems.filter(item=>["예정","진행","진행 중","완료"].includes(item.record.followupStatus)).length;
  const investedCount=researchItems.filter(item=>["투자완료","보육중"].includes(item.record.investmentStatus)).length;
  const checkCount=researchItems.filter(item=>researchNeedsCheck(item.record)).length;
  const researchRows=researchItems.map(item=>{const record=item.record;const companyId=item.company?.id||"";const categories=[researchNeedsCheck(record)?"needs":"",["예정","진행","진행 중","완료"].includes(record.followupStatus)?"followup":"",["투자완료","보육중"].includes(record.investmentStatus)?"invested":""].filter(Boolean).join(" ");const companyLabel=item.company?`<button class="entity-link" data-company="${item.company.id}">${esc(item.name)}</button>`:`<strong>${esc(item.name)}</strong>`;return `<tr data-research-row data-search="${esc([item.name,record.followupStatus,record.investmentStatus,record.source,record.memo].join(" ").toLowerCase())}" data-categories="${categories}"><td>${companyLabel}<small>${esc(item.eventIds.join(", "))}</small></td><td>${researchInlineSelect("followupStatus",record.followupStatus,p.id,companyId,item.name)}</td><td>${researchInlineSelect("investmentStatus",record.investmentStatus,p.id,companyId,item.name)}</td><td class="research-memo">${esc(record.memo||"조사 필요")}</td><td><button class="research-edit-button" data-edit-research data-investor-id="${p.id}" data-company-id="${companyId}" data-company-name="${esc(item.name)}">${researchNeedsCheck(record)?"현황 입력":"현황 수정"}</button></td></tr>`}).join("");
  const researchSection=`<section class="investor-detail-section investor-research-section"><header><div><h2>만난 기업 후속 현황</h2><p>포켓데이에서 만난 기업의 후속 미팅 여부와 투자 진행 상황을 조사하고 관리합니다.</p></div></header><div class="research-summary"><article><i>◎</i><span>전체 기업<strong>${researchItems.length}<em>개사</em></strong></span></article><article><i>▣</i><span>후속 미팅<strong>${followupCount}<em>개사</em></strong></span></article><article><i>▥</i><span>투자 완료<strong>${investedCount}<em>개사</em></strong></span></article><article class="needs"><i>!</i><span>확인 필요<strong>${checkCount}<em>개사</em></strong></span></article></div><div class="research-toolbar"><label><span>⌕</span><input type="search" data-research-search placeholder="기업명 검색" aria-label="만난 기업 검색" /></label><div class="research-filters"><button class="active" data-research-filter="all">전체</button><button data-research-filter="needs">확인 필요</button><button data-research-filter="followup">후속 미팅</button><button data-research-filter="invested">투자 완료</button></div></div><div class="research-table-wrap"><table class="research-table"><thead><tr><th>기업</th><th>후속 미팅</th><th>투자 상태</th><th>조사 메모</th><th>관리</th></tr></thead><tbody>${researchRows||`<tr><td colspan="5"><div class="empty">조사할 포켓데이 참여 기업이 없습니다.</div></td></tr>`}</tbody></table><div class="empty research-filter-empty" hidden>조건에 맞는 기업이 없습니다.</div></div></section>`;
  return `<div class="investor-detail-page"><button class="investor-detail-back" data-go="investors">← 심사역 목록</button><header class="investor-detail-hero"><span class="eyebrow">INVESTOR DETAIL</span><div class="investor-detail-identity"><div class="investor-detail-avatar">${initials(p.name)}</div><div><h1>${esc(p.name)}</h1><p>${esc(profileLine)}</p></div></div><button class="primary-button investor-detail-edit" data-edit-investor="${p.id}">정보 수정</button></header><section class="investor-detail-stats"><article><strong>${a.ms.length}</strong><span>전체 미팅</span></article><article><strong>${a.followups}</strong><span>후속 미팅</span></article><article><strong>${a.done}</strong><span>투자 완료</span></article></section><section class="investor-detail-section"><header><h2>기본 정보</h2><p>심사역의 소속과 투자 활동 기본 정보를 확인합니다.</p></header><div class="investor-info-grid full-page"><div class="investor-info-card"><i>▥</i><span><small>소속 투자사</small><strong>${esc(firm)}</strong></span></div><div class="investor-info-card"><i>₩</i><span><small>펀드</small><strong>${esc(p.fund||"미등록")}</strong></span></div><div class="investor-info-card"><i>◎</i><span><small>운영사 종류</small><strong class="operator-type-list">${operatorTypeBadges(operatorType)}</strong></span></div><div class="investor-info-card"><i>♙</i><span><small>직책</small><strong>${esc(title)}</strong></span></div><div class="investor-info-card"><i>✉</i><span><small>이메일</small><strong>${esc(email)}</strong></span></div><div class="investor-info-card"><i>⌕</i><span><small>연락처</small><strong>${esc(phone)}</strong></span></div><div class="investor-info-card"><i>◫</i><span><small>관심 분야</small><strong class="investor-focus-list">${focus}</strong></span></div></div></section><section class="investor-detail-section investor-pocketday-section"><header><div><h2>포켓데이에서 만난 기업</h2><p>${esc(p.name)} 심사역의 포켓데이 참여 회차별 기업 목록입니다.</p></div><span>${connections.length}회 · ${uniqueCompanies}개사</span></header><div class="investor-pocketday-list">${connectionRows||`<div class="empty">포켓데이 참여 기업 이력이 없습니다.</div>`}</div></section>${researchSection}<section class="investor-detail-section investor-history-section"><header><h2>연결된 전체 이력</h2><p>${esc(p.name)} 심사역과 연결된 미팅·투자·후속 기록입니다.</p></header><div class="investor-history-list">${a.ms.sort((x,y)=>y.date.localeCompare(x.date)).map(m=>`<article><time>${fmtDate(m.date)}</time><div><button class="entity-link" data-company="${m.companyId}">${esc(m.company.name)}</button><p>${esc(m.type)} · ${esc(m.memo)}</p></div><div class="investor-history-status">${badge(m.investmentStatus)}<span>후속 ${esc(m.followupStatus)}</span></div></article>`).join("")||`<div class="empty">연결된 이력이 없습니다.</div>`}</div></section></div>`;
}
function openCompany(id){const company=com(id);if(!company||company.deletedAt){showToast("삭제된 기업입니다. 기존 미팅 이력은 유지됩니다.");return}selectedCompanyId=id;switchView("companyDetail")}

function mergeCompanyPocketdayPanels(){
  const page=root.querySelector(".company-detail-page");
  if(!page)return;
  const historyPanel=page.querySelector(".pocketday-panel");
  const investorPanel=page.querySelector(".pocketday-investor-panel");
  if(!historyPanel||!investorPanel)return;
  const historyRows=[...historyPanel.querySelectorAll(".pocketday-detail-list>article")];
  const investorRows=[...investorPanel.querySelectorAll(".pocketday-investor-history>article")];
  const investorTotal=investorPanel.querySelector("header>span")?.textContent||"0명";
  const description=historyPanel.querySelector("header p");
  const summary=historyPanel.querySelector("header>span");
  if(description)description.textContent="포켓데이 참여 기록과 회차별로 만난 심사역을 함께 확인합니다.";
  if(summary)summary.textContent=`${historyRows.length}회 · ${investorTotal}`;
  const historyList=historyPanel.querySelector(".pocketday-detail-list");
  const searchBar=document.createElement("div");
  searchBar.className="pocketday-investor-search";
  searchBar.innerHTML='<label><span>⌕</span><input type="search" data-pocketday-investor-search placeholder="심사역 이름 또는 소속으로 검색" aria-label="포켓데이 참여 심사역 검색"></label>';
  historyPanel.insertBefore(searchBar,historyList);
  historyRows.forEach((row,index)=>{
    const investorList=investorRows[index]?.querySelector(".pocketday-investor-list");
    if(!investorList)return;
    row.classList.add("pocketday-merged-row");
    row.dataset.pocketdayInvestorRow="";
    investorList.querySelectorAll(":scope > div").forEach(card=>{card.dataset.investorSearch=card.textContent.trim().toLowerCase()});
    const investorSection=document.createElement("div");
    investorSection.className="pocketday-merged-investors";
    const label=document.createElement("strong");
    label.textContent=`참여 심사역 ${investorList.querySelectorAll(":scope > div").length}명`;
    investorSection.append(label,investorList);
    row.insertBefore(investorSection,row.lastElementChild);
  });
  const searchEmpty=document.createElement("div");
  searchEmpty.className="pocketday-investor-search-empty";
  searchEmpty.dataset.pocketdayInvestorSearchEmpty="";
  searchEmpty.hidden=true;
  searchEmpty.textContent="검색 결과가 없습니다.";
  historyList.after(searchEmpty);
  historyPanel.classList.add("pocketday-combined-panel");
  investorPanel.remove();
}
function render(){const meta=viewMeta[currentView]||viewMeta.dashboard;const roleHome=["companyHome","investorHome","investorReview","investorFeedback","investorMeetings","investorDetail","companyDetail"].includes(currentView);document.getElementById("pageHeading").hidden=roleHome;document.getElementById("pageEyebrow").textContent=meta[0];document.getElementById("pageTitle").textContent=meta[1];document.getElementById("pageSubtitle").textContent=meta[2];const data=visibleMeetings();root.innerHTML=currentView==="companyHome"?renderCompanyHome():currentView==="investorHome"?renderInvestorHome():currentView==="investorReview"?renderInvestorReview():currentView==="investorFeedback"?renderInvestorFeedback():currentView==="investorMeetings"?renderInvestorMeetings():currentView==="investorDetail"?renderInvestorDetail():currentView==="companyDetail"?renderCompanyDetail():currentView==="adminHome"?renderAnnualLinkage():currentView==="dashboard"?renderDashboard(data):currentView==="meetings"?renderMeetings(data):currentView==="investors"?renderInvestors():currentView==="companiesInProgress"?renderCompanies("진행중"):currentView==="companiesCompleted"?renderCompanies("완료"):currentView==="companies"?renderCompanies():currentView==="houses"?renderHouses():currentView==="pocketdaySchedule"?renderPocketdaySchedule():currentView==="followups"?renderFollowups(data):currentView==="annualLinkage"?renderAnnualLinkage():renderPipeline(data,true);mergeCompanyPocketdayPanels();if(currentRole==="admin")renderAdminSidebarStats();bindDynamic()}
