function removeCompanyMetadata(companyId){
  [companyRemainingRoundStorageKey,"pocket-crm-company-types-v1","pocket-crm-admin-company-terms-v1","pocket-crm-company-notes-v1"].forEach(key=>{
    let values={};
    try{values=JSON.parse(localStorage.getItem(key)||"{}")}catch{}
    if(!values||typeof values!=="object")values={};
    if(!(companyId in values))return;
    delete values[companyId];
    localStorage.setItem(key,JSON.stringify(values));
  });
  if(investorInterestCompanyIds.delete(companyId))saveInvestorInterestCompanies();
}
function deleteCompany(id){
  const company=com(id);
  if(!company||company.deletedAt){showToast("삭제할 기업을 찾지 못했습니다.");return}
  if(!window.confirm(`${company.name}을(를) 기업 목록에서 삭제할까요?\n기존 포켓데이와 미팅 이력은 유지됩니다.`))return;
  company.deletedAt=new Date().toISOString();
  removeCompanyMetadata(company.id);
  save();
  fillSelects();
  selectedCompanyId="";
  switchView("companies");
  showToast("기업을 목록에서 삭제했습니다. 기존 이력은 유지됩니다.");
}
function openResearchModal(investorId,companyName,companyId=""){
  const form=document.getElementById("researchForm");
  const record=researchRecord(investorId,companyId,companyName);
  form.reset();
  form.elements.investorId.value=investorId;
  form.elements.companyId.value=companyId;
  form.elements.companyName.value=companyName;
  form.elements.followupStatus.value=record.followupStatus||"미확인";
  form.elements.investmentStatus.value=normalizeResearchInvestmentStatus(record.investmentStatus);
  form.elements.memo.value=record.memo||"";
  document.getElementById("researchModalTitle").textContent=`${companyName} 후속 현황`;
  document.getElementById("researchModalIntro").textContent="후속 미팅과 투자 상태, 필요한 조사 메모를 기록해 주세요.";
  document.getElementById("researchModal").hidden=false;
  setTimeout(()=>form.elements.followupStatus.focus(),0);
}
function closeResearchModal(){document.getElementById("researchModal").hidden=true}
function applyResearchFilters(){
  const search=document.querySelector("[data-research-search]");
  const term=(search?.value||"").trim().toLowerCase();
  const filter=document.querySelector("[data-research-filter].active")?.dataset.researchFilter||"all";
  const rows=[...document.querySelectorAll("[data-research-row]")];
  rows.forEach(row=>{const searchMatch=!term||row.dataset.search.includes(term);const filterMatch=filter==="all"||row.dataset.categories.split(" ").includes(filter);row.hidden=!(searchMatch&&filterMatch)});
  const empty=document.querySelector(".research-filter-empty");
  if(empty)empty.hidden=!rows.length||rows.some(row=>!row.hidden);
}
